def create_palin(cnt):
    total = sum(v for k, v in list(cnt.items()))
    p = [None]*total

    lo = 0
    hi = total-1
    for k, v in sorted(cnt.items()):
        while v > 0:
            p[lo] = k
            p[hi] = k
            lo += 1
            hi -= 1
            v -= 2
    return str.join('', p)

def create_palin_odd(cnt):
    total = sum(v for k, v in list(cnt.items()))
    odd = [k for k, v in list(cnt.items()) if v%2 == 1][0]
