import collections


def bfs(u, adjList, vis):
    dq = collections.deque()

    dq.append(u)
    vis[u] = True
    edgeCnt = 0
    vertexCnt = 0

    while dq:
        u = dq.popleft()

        vertexCnt += 1
        edgeCnt += len(adjList[u])

        for v in adjList[u]:
            if not vis[v]:
                vis[v] = True
                dq.append(v)

    edgeCnt = edgeCnt // 2
    return bool(edgeCnt == ((vertexCnt * vertexCnt - vertexCnt) // 2))


