", "from collections import deque

def Hopcroft_Karp(adj, L):
    """
    Computes maximal matching in unweighted bipartite graph `adj`. Here `L` is
    a boolean array which gives the left part of the bipartite graph. If w is
    in adj[v], then precisely one of L[v], L[w] should be True.

    Returns (N, matching), where N is the cardinality of the matching, and
    matching is a list encoding the matched vertex (where a -1 indicates an
    unmatched vertex).
    """
    N = len(adj)
    matching = [-1 for _ in range(N)]

    while True:
        # If our matching changes, we need another iteration.
        extended = False

        # Do a BFS starting at all unmatched left nodes.
        sources = [v for v in range(N) if matching[v] == -1 and L[v]]

        # Keep track of your immediate predecessor in the BFS.
        # -1 means an unvisited node. Sources have themselves as predecessor.
        bfs_pred = [-1 for _ in range(N)]

        # Keep track of which BFS source started your subtree.
        # -1 means an unvisited node.
        bfs_source = [-1 for _ in range(N)]

        for v in sources:
            bfs_pred[v] = v
            bfs_source[v] = v

        queue = deque(sources)
        while len(queue) > 0:
            cur = queue.popleft()

            # If the node that started this subtree has been matched, stop growing the BFS.
            if matching[bfs_source[cur]] != -1:
                continue

            for nb in adj[cur]:
                if matching[nb] == -1:
                    # We have found an augmenting path. 
                    # Use a clever loop to use the path to update the matching.
                    while nb != -1:
                        matching[nb], matching[cur], nb, cur = cur, nb, matching[cur], bfs_pred[cur]
                    extended = True
                    break
                else:
                    new = matching[nb]
                    if bfs_pred[new] == -1:
                        bfs_pred[new] = cur
                        bfs_source[new] = bfs_source[cur]
                        queue.append(new)
        if not extended:
            break

    return sum(1 for x in matching if x != -1)//2, matching

