import unittest
import sys

###############################################################################
# Code Class (Main Program)
###############################################################################


class Code:
    """ Code representation """

    def __init__(self, test_inputs=None):
        """ Default constructor """

        it = iter(test_inputs.split("\n")) if test_inputs else None

        def uinput():
            return next(it) if it else sys.stdin.readline().rstrip()

        # Reading single elements
        [self.n, self.l, self.r] = list(map(int, uinput().split()))

    def bitlist(self, n):
        result = []
        while n > 0:
            result.append(n & 1)
            n = int(n/2)
        result.reverse()
        return result

    def period(self, i):
        return 2 << i

    def start(self, i):
        return (1 << i) - 1

    def count(self, s, p, l, r):
        start = 1 if (l - s) % p == 0 else 0
        return ((r - s) // p) - ((l - s) // p) + start

    def calculate(self):
        """ Main calcualtion function of the class """

        result = 0
        bl = self.bitlist(self.n)
        for (i, n) in enumerate(bl):
            if n == 1:
                period = self.period(i)
                start = self.start(i)
                result += self.count(start, period, self.l-1, self.r-1)

        return str(result)

